#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_copy_stack_create_stack_failure(void) {
    // Setup: create a valid source stack
    DArrayStack *src = create_stack(10);
    TEST_ASSERT_NOT_NULL(src);
    // Push some data to make it non-empty
    int push_result = push(src, 42);
    TEST_ASSERT_EQUAL_INT(0, push_result); // push successful

    // Force create_stack to fail when copy_stack calls it
    // create_stack performs 2 allocations: struct and array
    // We need to fail the first allocation inside create_stack
    // Since src is already created (2 allocations), we need to fail the 3rd allocation
    malloc_fail_after(2); // First 2 allocations (src) succeed, next one fails

    // Test: copy_stack should return NULL because create_stack fails
    DArrayStack *dest = copy_stack(src);
    TEST_ASSERT_NULL(dest);
    // Clean up dest if copy_stack partially allocated it
    if (dest != NULL) {
        free_stack(dest);
    }

    // Cleanup
    free_stack(src);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_copy_stack_create_stack_failure);
    return UNITY_END();
}

